import json
from copy import deepcopy

def zebra_puzzle_solver():
    houses = [1, 2, 3, 4, 5]

    categories = {
        "name": ["Bob", "Eric", "Arnold", "Alice", "Peter"],
        "favorite color": ["blue", "green", "white", "yellow", "red"],
        "phone models": ["huawei p50", "samsung galaxy s21", "oneplus 9", "iphone 13", "google pixel 6"],
        "occupation": ["artist", "teacher", "doctor", "engineer", "lawyer"],
    }

    # Variables are tuples (category, item)
    variables = []
    for cat, items in categories.items():
        for item in items:
            variables.append((cat, item))

    # Initialize domains
    domains = {}
    for var in variables:
        domains[var] = set(houses)

    # Apply initial domain reductions based on direct clues
    # 2. Bob is in the second house.
    domains[("name", "Bob")] = {2}
    # 5. The person whose favorite color is green is not in the fifth house.
    domains[("favorite color", "green")] -= {5}
    # 7. The person who loves blue is directly left of the person whose favorite color is red.
    # This implies blue cannot be 5 and red cannot be 1.
    domains[("favorite color", "blue")] -= {5}
    domains[("favorite color", "red")] -= {1}

    # Equality constraints pairs
    equal_pairs = set()
    # 3. Samsung Galaxy S21 is the doctor.
    equal_pairs.add((("phone models", "samsung galaxy s21"), ("occupation", "doctor")))
    # 4. The doctor loves blue. -> doctor == blue
    equal_pairs.add((("occupation", "doctor"), ("favorite color", "blue")))
    # Also add s21 == blue via transitivity to help propagation
    equal_pairs.add((("phone models", "samsung galaxy s21"), ("favorite color", "blue")))
    # 6. Lawyer uses OnePlus 9.
    equal_pairs.add((("occupation", "lawyer"), ("phone models", "oneplus 9")))
    # 10. Arnold is the engineer.
    equal_pairs.add((("name", "Arnold"), ("occupation", "engineer")))
    # 11. Alice loves yellow.
    equal_pairs.add((("name", "Alice"), ("favorite color", "yellow")))
    # 12. Google Pixel 6 is Eric.
    equal_pairs.add((("phone models", "google pixel 6"), ("name", "Eric")))
    # 13. Google Pixel 6 is the teacher.
    equal_pairs.add((("phone models", "google pixel 6"), ("occupation", "teacher")))
    # Also add teacher == Eric to strengthen propagation
    equal_pairs.add((("occupation", "teacher"), ("name", "Eric")))

    # Convert set to list for stable iteration
    equal_pairs = list(equal_pairs)

    # Helper functions
    def peers_in_category(var):
        cat, item = var
        return [(cat, other) for other in categories[cat] if other != item]

    def apply_equality(domains, assignment):
        changed = False
        for (a, b) in equal_pairs:
            va = next(iter(assignment[a:a])) if False else assignment.get(a)
            vb = assignment.get(b)
            # if one side assigned, set other's domain to that value
            if va is not None:
                if domains[b] != {va}:
                    if va not in domains[b]:
                        return None, True  # conflict
                    domains[b] = {va}
                    changed = True
            if vb is not None:
                if domains[a] != {vb}:
                    if vb not in domains[a]:
                        return None, True
                    domains[a] = {vb}
                    changed = True
            # Also enforce domain intersection if both unassigned but domains don't overlap? Not necessary but safe:
            if va is None and vb is None:
                inter = domains[a].intersection(domains[b])
                if not inter:
                    return None, True
                if domains[a] != inter:
                    domains[a] = set(inter)
                    changed = True
                if domains[b] != inter:
                    domains[b] = set(inter)
                    changed = True
        return changed, False

    def propagate(domains, assignment):
        # Repeatedly apply constraints until fixpoint or conflict
        while True:
            changed = False

            # If any variable has empty domain -> conflict
            for var, dom in domains.items():
                if len(dom) == 0:
                    return False

            # If any variable has domain size 1, assign it
            for var, dom in list(domains.items()):
                if var not in assignment and len(dom) == 1:
                    val = next(iter(dom))
                    assignment[var] = val
                    changed = True

            # All-different constraint by category: remove assigned positions from peers
            for cat, items in categories.items():
                assigned_positions = set()
                for item in items:
                    v = (cat, item)
                    if v in assignment:
                        assigned_positions.add(assignment[v])
                for item in items:
                    v = (cat, item)
                    if v not in assignment:
                        new_dom = domains[v] - assigned_positions
                        if new_dom != domains[v]:
                            if not new_dom:
                                return False
                            domains[v] = new_dom
                            changed = True

            # Apply equality constraints propagation
            eq_changed, conflict = apply_equality(domains, assignment)
            if conflict:
                return False
            if eq_changed:
                changed = True

            # Apply specific relative constraints
            # 7. blue is directly left of red: pos(blue) + 1 == pos(red)
            blue = ("favorite color", "blue")
            red = ("favorite color", "red")
            if blue in assignment:
                bpos = assignment[blue]
                # blue cannot be 5 (already enforced), red must be bpos+1
                if bpos == 5:
                    return False
                needed = bpos + 1
                if needed < 1 or needed > 5:
                    return False
                if domains[red] != {needed}:
                    if needed not in domains[red]:
                        return False
                    domains[red] = {needed}
                    changed = True
            if red in assignment:
                rpos = assignment[red]
                # red cannot be 1, blue must be rpos-1
                if rpos == 1:
                    return False
                needed = rpos - 1
                if needed < 1 or needed > 5:
                    return False
                if domains[blue] != {needed}:
                    if needed not in domains[blue]:
                        return False
                    domains[blue] = {needed}
                    changed = True

            # 1. engineer > lawyer
            eng = ("occupation", "engineer")
            law = ("occupation", "lawyer")
            if eng in assignment:
                epos = assignment[eng]
                # lawyer must be < epos
                allowed = set([p for p in houses if p < epos])
                new_dom = domains[law].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[law]:
                    domains[law] = new_dom
                    changed = True
            if law in assignment:
                lpos = assignment[law]
                # engineer must be > lpos
                allowed = set([p for p in houses if p > lpos])
                new_dom = domains[eng].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[eng]:
                    domains[eng] = new_dom
                    changed = True

            # 8. lawyer > S21
            s21 = ("phone models", "samsung galaxy s21")
            if s21 in assignment:
                s = assignment[s21]
                allowed = set([p for p in houses if p > s])
                new_dom = domains[law].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[law]:
                    domains[law] = new_dom
                    changed = True
            if law in assignment:
                l = assignment[law]
                allowed = set([p for p in houses if p < l])
                new_dom = domains[s21].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[s21]:
                    domains[s21] = new_dom
                    changed = True

            # 14. red > teacher
            teacher = ("occupation", "teacher")
            if teacher in assignment:
                t = assignment[teacher]
                allowed = set([p for p in houses if p > t])
                new_dom = domains[red].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[red]:
                    domains[red] = new_dom
                    changed = True
            if red in assignment:
                r = assignment[red]
                allowed = set([p for p in houses if p < r])
                new_dom = domains[teacher].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[teacher]:
                    domains[teacher] = new_dom
                    changed = True

            # 9. One house between Pixel6 and Huawei P50: |pos(Pixel6) - pos(Huawei)| == 2
            pixel = ("phone models", "google pixel 6")
            huawei = ("phone models", "huawei p50")
            if pixel in assignment:
                ppos = assignment[pixel]
                allowed = set()
                if ppos - 2 >= 1:
                    allowed.add(ppos - 2)
                if ppos + 2 <= 5:
                    allowed.add(ppos + 2)
                new_dom = domains[huawei].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[huawei]:
                    domains[huawei] = new_dom
                    changed = True
            if huawei in assignment:
                hpos = assignment[huawei]
                allowed = set()
                if hpos - 2 >= 1:
                    allowed.add(hpos - 2)
                if hpos + 2 <= 5:
                    allowed.add(hpos + 2)
                new_dom = domains[pixel].intersection(allowed)
                if not new_dom:
                    return False
                if new_dom != domains[pixel]:
                    domains[pixel] = new_dom
                    changed = True

            if not changed:
                break

        return True

    def is_complete(assignment):
        return len(assignment) == len(variables)

    def is_consistent(assignment):
        # Check constraints that can be violated with current assignment
        def pos(var):
            return assignment.get(var)

        # All-different per category
        for cat, items in categories.items():
            seen = set()
            for item in items:
                v = (cat, item)
                if v in assignment:
                    if assignment[v] in seen:
                        return False
                    seen.add(assignment[v])

        # 1. engineer right of lawyer
        p_eng = pos(("occupation", "engineer"))
        p_law = pos(("occupation", "lawyer"))
        if p_eng is not None and p_law is not None:
            if not (p_eng > p_law):
                return False

        # 3. S21 == doctor
        p_s21 = pos(("phone models", "samsung galaxy s21"))
        p_doc = pos(("occupation", "doctor"))
        if p_s21 is not None and p_doc is not None and p_s21 != p_doc:
            return False

        # 4. doctor == blue
        p_blue = pos(("favorite color", "blue"))
        if p_doc is not None and p_blue is not None and p_doc != p_blue:
            return False

        # 5. green != 5
        p_green = pos(("favorite color", "green"))
        if p_green is not None and p_green == 5:
            return False

        # 6. lawyer == oneplus 9
        p_op9 = pos(("phone models", "oneplus 9"))
        if p_law is not None and p_op9 is not None and p_law != p_op9:
            return False

        # 7. blue directly left of red
        p_red = pos(("favorite color", "red"))
        if p_blue is not None and p_red is not None:
            if p_blue + 1 != p_red:
                return False
        if p_blue is not None and p_blue == 5:
            return False
        if p_red is not None and p_red == 1:
            return False

        # 8. lawyer right of S21
        if p_law is not None and p_s21 is not None:
            if not (p_law > p_s21):
                return False

        # 9. one house between Pixel6 and Huawei
        p_pixel = pos(("phone models", "google pixel 6"))
        p_huawei = pos(("phone models", "huawei p50"))
        if p_pixel is not None and p_huawei is not None:
            if abs(p_pixel - p_huawei) != 2:
                return False

        # 10. Arnold is the engineer
        p_arnold = pos(("name", "Arnold"))
        if p_arnold is not None and p_eng is not None and p_arnold != p_eng:
            return False

        # 11. Alice yellow
        p_alice = pos(("name", "Alice"))
        p_yellow = pos(("favorite color", "yellow"))
        if p_alice is not None and p_yellow is not None and p_alice != p_yellow:
            return False

        # 12. Pixel6 is Eric
        p_eric = pos(("name", "Eric"))
        if p_pixel is not None and p_eric is not None and p_pixel != p_eric:
            return False

        # 13. Pixel6 is teacher
        p_teacher = pos(("occupation", "teacher"))
        if p_pixel is not None and p_teacher is not None and p_pixel != p_teacher:
            return False

        # 14. red right of teacher
        if p_red is not None and p_teacher is not None:
            if not (p_red > p_teacher):
                return False

        # 2. Bob is in the second house
        p_bob = pos(("name", "Bob"))
        if p_bob is not None and p_bob != 2:
            return False

        return True

    def select_unassigned_variable(domains, assignment):
        # Minimum Remaining Values heuristic
        unassigned = [v for v in variables if v not in assignment]
        # Sort by domain size, then by category to stabilize
        unassigned.sort(key=lambda v: (len(domains[v]), v[0], v[1]))
        return unassigned[0] if unassigned else None

    def backtrack(domains, assignment):
        if not is_consistent(assignment):
            return None

        if not propagate(domains, assignment):
            return None

        if is_complete(assignment):
            return assignment

        var = select_unassigned_variable(domains, assignment)
        if var is None:
            return None

        # Try values in domain
        for val in sorted(domains[var]):
            # Copy domains and assignment
            new_domains = deepcopy(domains)
            new_assignment = assignment.copy()
            # Assign
            new_domains[var] = {val}
            new_assignment[var] = val
            result = backtrack(new_domains, new_assignment)
            if result is not None:
                return result

        return None

    # Start search
    solution_assignment = backtrack(deepcopy(domains), {})

    if solution_assignment is None:
        raise RuntimeError("No solution found")

    # Build output rows
    header = ["House", "name", "favorite color", "phone models", "occupation"]
    rows = []
    for house in houses:
        # Find the item in each category with this house number
        name_val = next(item for item in categories["name"] if solution_assignment[("name", item)] == house)
        color_val = next(item for item in categories["favorite color"] if solution_assignment[("favorite color", item)] == house)
        phone_val = next(item for item in categories["phone models"] if solution_assignment[("phone models", item)] == house)
        job_val = next(item for item in categories["occupation"] if solution_assignment[("occupation", item)] == house)
        rows.append([str(house), name_val, color_val, phone_val, job_val])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = zebra_puzzle_solver()
    print(json.dumps(result, indent=2))
